  private static func localized(_ key: String, _ english: String) -> String {
    NSLocalizedString(key, tableName: "Watch", value: english, comment: "")
  }

  /// Puts each value where the text has its `{name}`.
  private static func filled(_ template: String, _ values: [String: String]) -> String {
    var out = ""
    var rest = Substring(template)
    while let open = rest.firstIndex(of: "{"), let close = rest[open...].firstIndex(of: "}") {
      out += rest[..<open]
      out += values[String(rest[rest.index(after: open)..<close])] ?? String(rest[open...close])
      rest = rest[rest.index(after: close)...]
    }
    return out + rest
  }
